CREATE OR REPLACE FUNCTION public.protect_land_trade_coins() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN IF TG_OP='INSERT' THEN IF NEW.land_trade_coins<>0 THEN RAISE EXCEPTION 'Trade coins are managed by tile transactions'; END IF; ELSIF NEW.land_trade_coins IS DISTINCT FROM OLD.land_trade_coins THEN RAISE EXCEPTION 'Trade coins are managed by tile transactions'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_land_trade_coins_on_join BEFORE INSERT ON public.world_members FOR EACH ROW EXECUTE FUNCTION public.protect_land_trade_coins();